CREATE TABLE equation_document (id INTEGER PRIMARY KEY CHECK(id=1));
CREATE TABLE equation_notation_child (id INTEGER PRIMARY KEY CHECK(id=1), document_id INTEGER NOT NULL REFERENCES equation_document(id), child_id TEXT NOT NULL, target_artifact_id TEXT NOT NULL, target_artifact_kind TEXT NOT NULL, target_standard TEXT NOT NULL, target_subset TEXT NOT NULL);
CREATE TABLE equation_results_child (id INTEGER PRIMARY KEY CHECK(id=1), document_id INTEGER NOT NULL REFERENCES equation_document(id), child_id TEXT NOT NULL, target_artifact_id TEXT NOT NULL, target_artifact_kind TEXT NOT NULL, target_standard TEXT NOT NULL, target_subset TEXT NOT NULL);
CREATE TABLE equation_computed_child (id INTEGER PRIMARY KEY CHECK(id=1), document_id INTEGER NOT NULL REFERENCES equation_document(id), child_id TEXT NOT NULL, target_artifact_id TEXT NOT NULL, target_artifact_kind TEXT NOT NULL, target_standard TEXT NOT NULL, target_subset TEXT NOT NULL);
CREATE TABLE equation_expression (id INTEGER PRIMARY KEY CHECK(id=1), document_id INTEGER NOT NULL REFERENCES equation_document(id), root_node_id INTEGER NOT NULL REFERENCES equation_node(id), next_label_high INTEGER NOT NULL CHECK(next_label_high BETWEEN 0 AND 4294967295), next_label_low INTEGER NOT NULL CHECK(next_label_low BETWEEN 0 AND 4294967295));
CREATE TABLE equation_node (id INTEGER PRIMARY KEY, expression_id INTEGER NOT NULL REFERENCES equation_expression(id), label_high INTEGER NOT NULL CHECK(label_high BETWEEN 0 AND 4294967295), label_low INTEGER NOT NULL CHECK(label_low BETWEEN 0 AND 4294967295), kind TEXT NOT NULL CHECK(kind IN ('integer','rational','symbol','add','mul','pow')));
CREATE TABLE equation_integer (node_id INTEGER PRIMARY KEY REFERENCES equation_node(id), lexeme TEXT NOT NULL);
CREATE TABLE equation_rational (node_id INTEGER PRIMARY KEY REFERENCES equation_node(id), numerator_lexeme TEXT NOT NULL, denominator_lexeme TEXT NOT NULL);
CREATE TABLE equation_symbol (node_id INTEGER PRIMARY KEY REFERENCES equation_node(id), name TEXT NOT NULL);
CREATE TABLE equation_add (node_id INTEGER PRIMARY KEY REFERENCES equation_node(id));
CREATE TABLE equation_mul (node_id INTEGER PRIMARY KEY REFERENCES equation_node(id));
CREATE TABLE equation_pow (node_id INTEGER PRIMARY KEY REFERENCES equation_node(id), base_node_id INTEGER NOT NULL REFERENCES equation_node(id), exponent_node_id INTEGER NOT NULL REFERENCES equation_node(id));
CREATE TABLE equation_add_term (id INTEGER PRIMARY KEY, add_node_id INTEGER NOT NULL REFERENCES equation_add(node_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), node_id INTEGER NOT NULL REFERENCES equation_node(id));
CREATE TABLE equation_mul_factor (id INTEGER PRIMARY KEY, mul_node_id INTEGER NOT NULL REFERENCES equation_mul(node_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), node_id INTEGER NOT NULL REFERENCES equation_node(id));
